<script lang="ts">
 import {readConfig,saveConfiguration,inRange,type Firmware,type DeviceState} from './api';
 import {readChannels,savedChannels} from './channels';
 import {lightingKeys,decodeLighting,lightingPatch,timeLapseState,type LightingValues} from './advanced';
 import ActionButton from './ui/ActionButton.svelte';
 import DraftBar from './ui/DraftBar.svelte';
 import StateBadge from './ui/StateBadge.svelte';
 import ChannelIdentity from './ui/ChannelIdentity.svelte';
 import RawMeter from './ui/RawMeter.svelte';
 import LevelControl from './ui/LevelControl.svelte';
 let {active,busy,firmware,snapshot,stale,feedback,perform,command,refresh,readback,onedit}:{active:boolean;busy:boolean;firmware:Firmware;snapshot:DeviceState;stale:boolean;feedback:string;perform:(task:()=>Promise<void>,success:string,failure:string,pending:string)=>Promise<boolean>;command:(value:{pwms?:Record<string,number>;timewarp?:number})=>Promise<void>;refresh:()=>void;readback:()=>Promise<void>;onedit:()=>void}=$props();
 let draft=$state<LightingValues>(),base=$state<LightingValues>({}),attempted=$state(false);
 const channels=$derived(Array.from({length:firmware.pwm_count},(_,i)=>i+1));
 function assessment(scope:'minimum'|'expert'){try{return {patch:draft?lightingPatch(draft,base,firmware.pwm_count,scope):{},error:''};}catch(e){return {patch:{},error:(e as Error).message};}}
 const minimum=$derived(assessment('minimum')),expert=$derived(assessment('expert')),mode=$derived(timeLapseState(snapshot,stale));
 const flags=[['higherminimum','Raise low-end minimum'],['oldfade','Use original dimming algorithm']];
 function set(key:string,value:unknown){if(draft){draft[key]=value;onedit();}}
 async function load(refresh=false){attempted=true;await perform(async()=>{const next=decodeLighting(await readConfig(lightingKeys(firmware.pwm_count)),firmware.pwm_count);const identities=await readChannels(firmware.pwm_count,refresh);base=JSON.parse(JSON.stringify(next));draft=next;savedChannels.set(identities);},'Lighting settings loaded','Could not load lighting settings. Draft kept; explicitly reload.','Reading lighting settings…');}
 async function save(scope:'minimum'|'expert',event:SubmitEvent){event.preventDefault();const result=assessment(scope);if(result.error||!Object.keys(result.patch).length)return;await perform(async()=>{await saveConfiguration(result.patch,firmware);await readback();Object.assign(base,result.patch);},scope==='minimum'?'Minimum settings saved and verified':'Dimming settings saved and verified','Could not confirm lighting settings. Draft kept; reload to verify or explicitly retry Save.','Saving lighting settings…');}
 async function preview(n:number){const value=draft?.[`pwm#${n}#min`];if(inRange(value,1000))await command({pwms:{[n]:value}});}
</script>
<div hidden={!active} class="lighting-tools">
 <div class="heading"><div><h1>Lighting tools</h1><p>Temporary operations and advanced dimming settings.</p></div></div>
 <section class="time-lapse" aria-label="Time-lapse"><div class="operation"><div><h2>Time-lapse</h2><p>Reported state <StateBadge tone={mode==='Active'?'active':mode==='Off'?'neutral':'draft'}>{mode}</StateBadge></p></div><div class="actions"><ActionButton disabled={busy||mode==='Unknown'||mode==='Uncertain'} onclick={()=>command({timewarp:1})}>Start time-lapse</ActionButton><ActionButton secondary disabled={busy} onclick={()=>command({timewarp:0})}>Stop time-lapse</ActionButton></div></div>
 <div class="read-state"><ActionButton secondary disabled={busy} onclick={refresh}>Refresh lighting state</ActionButton></div><p>A temporary accelerated planning run. It changes controller output and bypasses weather effects; service, fixed and other forced controls can take precedence. Start again restarts the run. Stop returns to ordinary planning time, not the previous raw output.</p>
 <p>Configuration reloads and restart also end time-lapse. After disconnection its state is uncertain: refresh or explicitly Stop. Leaving this page does not stop it; commands are never automatically retried.</p></section>
 <nav aria-label="Lighting tools sections"><a href="#minimum-settings" onclick={e=>{e.preventDefault();document.getElementById('minimum-settings')?.scrollIntoView({block:'start'});}}>Minimum output</a><a href="#expert-settings" onclick={e=>{e.preventDefault();document.getElementById('expert-settings')?.scrollIntoView({block:'start'});}}>Expert dimming</a><a href="#schedules">Schedules and raw curves →</a></nav>
 <div class="load-row"><ActionButton secondary disabled={busy} onclick={()=>load(true)}>{draft?'Reload lighting settings':'Load lighting settings'}</ActionButton><p>Reload replaces both settings drafts. No settings are loaded automatically.</p></div>
 {#if draft}
 <section id="minimum-settings" aria-label="Minimum output settings"><h2>Minimum output</h2><p>Set a stored minimum from 0–1000 raw; 0 disables the minimum. Edit locally, then use Preview only when you intend to command an output. Saving the setting is a separate action.</p>
 <p class="notice">Preview sends a live raw command. Fixed-mode channels retain that command, including after restart; other planning usually resumes after about a minute. Preview does not stop service mode or save the minimum. It does not establish a lamp’s physical switch-on threshold.</p>
 <form onsubmit={e=>save('minimum',e)} novalidate><DraftBar dirty={!!Object.keys(minimum.patch).length||!!minimum.error} {busy} {feedback} disabled={!Object.keys(minimum.patch).length||!!minimum.error} label="Save minimum settings" scope="minimum " detail="Only changed minimum settings are saved; output is read independently."/>
 {#if minimum.error}<p class="error" role="alert">{minimum.error}</p>{/if}
 <div class="channel-grid">{#each channels as n}{@const key=`pwm#${n}#min`}<section class="channel-setting"><div class="row-title"><h3><ChannelIdentity number={n}/></h3><span>Reported{stale?' · stale':''}: <strong>{snapshot.pwms[String(n)]} raw</strong></span></div><RawMeter value={snapshot.pwms[String(n)]} {stale}/>
 <p>Saved minimum: {JSON.stringify(base[key])} raw{draft[`pwm#${n}#onoff`]===true?' · Binary channel: minimum does not control on/off output.':''}</p>
 {#if typeof base[key]!=='number'}<p>Unknown stored value is preserved until explicitly replaced.</p>{/if}
 <div class="minimum-control"><LevelControl id={`minimum-${n}`} label={`Channel ${n} minimum raw`} max={1000} disabled={busy} bind:value={()=>typeof draft![key]==='number'?draft![key] as number:undefined,v=>set(key,v)}/><ActionButton secondary label={`Preview channel ${n} minimum`} disabled={busy||!inRange(draft[key],1000)} onclick={()=>preview(n)}>Preview</ActionButton></div></section>{/each}</div></form></section>
 <section id="expert-settings" aria-label="Expert dimming settings"><h2>Expert dimming</h2><p>Compatibility settings for existing lighting hardware. These are raw algorithm limits, not percentages or measurements. No hardware model is inferred from these settings.</p>
 <form onsubmit={e=>save('expert',e)} novalidate><DraftBar dirty={!!Object.keys(expert.patch).length||!!expert.error} {busy} {feedback} disabled={!Object.keys(expert.patch).length||!!expert.error} label="Save dimming settings" scope="dimming " detail="Saves changed compatibility settings without saving minimum drafts."/>
 {#if expert.error}<p class="error" role="alert">{expert.error}</p>{/if}
 <fieldset disabled={busy}><legend class="visually-hidden">Dimming settings</legend><div class="flags">{#each flags as [key,label]}{#if typeof draft[key]==='boolean'}<label class="check"><input type="checkbox" checked={draft[key]===true} onchange={e=>set(key,e.currentTarget.checked)}/>{label}</label>{:else}<label>{label}<select value="unknown" onchange={e=>set(key,e.currentTarget.value==='true')}><option value="unknown" disabled>Unknown — preserved</option><option value="false">Off</option><option value="true">On</option></select></label>{/if}{/each}</div>
 <p>Raise low-end minimum applies the firmware’s compatibility floor. Original dimming algorithm changes low-end conversion. Defaults are off; neither setting proves physical brightness or hardware compatibility.</p>
 <div class="channel-grid">{#each channels as n}{@const key=`pwm#${n}#max`}{@const smart=`pwm#${n}#nosmart`}<section class="channel-setting"><h3><ChannelIdentity number={n}/></h3><div class="expert-controls"><label>Maximum · raw<input type="number" min="10" max="1000" step="1" aria-label={`Channel ${n} maximum raw`} value={typeof draft[key]==='number'?draft[key] as number:undefined} oninput={e=>set(key,e.currentTarget.value===''?undefined:Number(e.currentTarget.value))} aria-invalid={JSON.stringify(draft[key])!==JSON.stringify(base[key])&&(!inRange(draft[key],1000)||(draft[key] as number)<10)}/></label>
 <p>Saved maximum: {JSON.stringify(base[key])} raw</p>{#if typeof draft[smart]==='boolean'}<label class="check"><input type="checkbox" aria-label={`Channel ${n} disable SmartControl compensation`} checked={draft[smart]===true} onchange={e=>set(smart,e.currentTarget.checked)}/>Disable SmartControl compensation</label>{:else}<label>SmartControl disable<select aria-label={`Channel ${n} disable SmartControl compensation`} value="unknown" onchange={e=>set(smart,e.currentTarget.value==='true')}><option value="unknown" disabled>Unknown — preserved</option><option value="false">Off</option><option value="true">On</option></select></label>{/if}
 </div>{#if draft[`pwm#${n}#onoff`]===true||draft[smart]===true}<p>The firmware bypasses the configured maximum for binary channels or disabled SmartControl compensation.</p>{/if}</section>{/each}</div></fieldset></form></section>
 {:else}<p>{busy?'Reading lighting settings…':attempted?'Settings unavailable. Use Load lighting settings to retry.':'Load saved settings before editing. Time-lapse commands remain independent.'}</p>{/if}
</div>
<style>
 .lighting-tools{font-size:15px;color:var(--sr-ink)}.heading,.operation,.load-row{display:flex;justify-content:space-between;align-items:center;gap:24px;margin:16px 0}.heading h1{font-size:var(--sr-title);font-weight:600;letter-spacing:-1px;margin:0}h2{font-size:20px;margin:0 0 12px}h3{font-size:15px;margin:0}p{font-size:13px;line-height:1.6;color:var(--sr-muted);max-width:110ch;margin:8px 0 14px}.time-lapse{border-left:2px solid var(--sr-accent);background:var(--sr-surface);padding:16px 20px}.operation{margin:0}.actions{display:flex;gap:12px;flex-wrap:wrap}nav{display:flex;gap:20px;flex-wrap:wrap;border:0;margin:16px 0}nav a{min-height:44px;display:inline-flex;align-items:center;font-size:14px}#minimum-settings,#expert-settings{margin:28px 0;scroll-margin-top:16px}.notice{border-left:2px solid var(--sr-accent);padding:8px 16px}.channel-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 32px}.channel-setting{border-bottom:1px solid var(--sr-line);padding:16px 0;min-width:0}.row-title{display:flex;justify-content:space-between;align-items:center;gap:16px}.row-title span{font-size:13px;color:var(--sr-muted)}.row-title strong{color:var(--sr-ink);font-family:var(--sr-mono)}.minimum-control{display:grid;grid-template-columns:minmax(0,1fr) 90px;gap:12px;align-items:center}.read-state{margin:12px 0}.expert-controls{display:grid;grid-template-columns:180px minmax(0,1fr);column-gap:24px;align-items:center}.expert-controls>p{grid-row:2}.expert-controls>.check{grid-column:2;grid-row:1/3}.error{color:var(--sr-error)}fieldset{margin:0;border:0;padding:0;min-width:0}.flags{display:flex;gap:24px;flex-wrap:wrap}label{display:block;font-size:14px;margin:12px 0}.check{display:flex;align-items:center;gap:10px;min-height:44px}input[type=checkbox]{width:20px;height:20px;flex-shrink:0}input[type=number],select{display:block;width:100%;max-width:260px;min-height:44px;margin-top:8px;padding:8px 12px;color:var(--sr-ink);background:var(--sr-input);border:1px solid var(--sr-control-line);border-radius:var(--sr-radius);font-size:16px}input[aria-invalid=true]{border-color:var(--sr-error)}
 @media(max-width:800px){.channel-grid{grid-template-columns:1fr}.heading{align-items:flex-start;flex-direction:column}.operation{align-items:flex-start;flex-direction:column;gap:12px}.load-row{align-items:flex-start;flex-direction:column;gap:4px}.row-title{align-items:flex-start;flex-direction:column;gap:6px}.time-lapse{padding:16px}.flags{gap:0}.expert-controls{grid-template-columns:minmax(0,1fr)}.expert-controls>.check{grid-column:auto;grid-row:auto}.heading{gap:0;margin-top:8px}.heading p{margin-bottom:0}.minimum-control{grid-template-columns:minmax(0,1fr)}input[type=number],select{max-width:none}}
</style>
